import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CmvPqeTF.js";const u=JSON.parse('{"title":"SSH 密钥管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keys.md","filePath":"guide/keys.md","lastUpdated":1788361893000}'),r={name:"guide/keys.md"};function h(s,t,c,i,n,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ssh-密钥管理" tabindex="-1">SSH 密钥管理 <a class="header-anchor" href="#ssh-密钥管理" aria-label="Permalink to &quot;SSH 密钥管理&quot;">​</a></h1><p>侧栏「密钥」面板（ActivityBar 第二个图标）直接管理 <code>~/.ssh</code> 目录下的密钥对：生成、粘贴导入、复制、重命名、删除。</p><hr><h2 id="_1-密钥列表" tabindex="-1">1. 密钥列表 <a class="header-anchor" href="#_1-密钥列表" aria-label="Permalink to &quot;1. 密钥列表&quot;">​</a></h2><p>列表读取 <code>~/.ssh</code> 下的私钥文件（递归扫描，跳过 <code>.pub</code>、证书、<code>known_hosts</code>、<code>authorized_keys</code> 等非私钥文件），每条显示：</p><table tabindex="0"><thead><tr><th>信息</th><th>说明</th></tr></thead><tbody><tr><td>类型徽章</td><td>RSA / Ed25519 / ECDSA / DSA（按公钥算法）</td></tr><tr><td>文件名</td><td>相对 <code>~/.ssh</code> 的路径</td></tr><tr><td>指纹</td><td>公钥指纹</td></tr><tr><td>注释</td><td>公钥尾部的 comment（通常 <code>user@host</code>）</td></tr><tr><td>🔒 锁图标</td><td>该私钥有口令保护</td></tr></tbody></table><p><code>~/.ssh</code> 中没有密钥时显示「未在 ~/.ssh 中找到 SSH 密钥」。工具栏三个按钮：<strong>刷新</strong>、<strong>生成密钥</strong>、<strong>新建密钥</strong>（粘贴导入）。</p><h2 id="_2-生成密钥" tabindex="-1">2. 生成密钥 <a class="header-anchor" href="#_2-生成密钥" aria-label="Permalink to &quot;2. 生成密钥&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>密钥类型</td><td>Ed25519 / RSA / ECDSA</td></tr><tr><td>强度</td><td>RSA：2048 / 3072 / 4096；ECDSA：256 / 384 / 521（Ed25519 无此项）</td></tr><tr><td>文件名</td><td>切换类型时自动给出默认名（<code>id_ed25519</code> / <code>id_rsa</code> / <code>id_ecdsa</code>）</td></tr><tr><td>注释</td><td>可选，占位提示 <code>user@host</code></td></tr><tr><td>密钥口令</td><td>可选，为私钥加口令</td></tr></tbody></table><p>生成结果：私钥写入 <code>~/.ssh/&lt;文件名&gt;</code>（权限 0600），公钥写入 <code>~/.ssh/&lt;文件名&gt;.pub</code>（0644）。</p><blockquote><p>RSA 强度低于 2048 时后端强制使用 4096。</p></blockquote><h2 id="_3-粘贴导入-新建密钥" tabindex="-1">3. 粘贴导入（新建密钥） <a class="header-anchor" href="#_3-粘贴导入-新建密钥" aria-label="Permalink to &quot;3. 粘贴导入（新建密钥）&quot;">​</a></h2><p>填写文件名（必填）+ 粘贴私钥内容（必填）+ 公钥内容（可选），保存即写入 <code>~/.ssh</code>。适合把已有密钥从别处迁移进来。</p><h2 id="_4-密钥操作" tabindex="-1">4. 密钥操作 <a class="header-anchor" href="#_4-密钥操作" aria-label="Permalink to &quot;4. 密钥操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>入口</th><th>说明</th></tr></thead><tbody><tr><td>复制公钥</td><td>hover 快捷按钮 / 右键菜单</td><td>复制 <code>.pub</code> 内容，适合添加到服务器 <code>authorized_keys</code></td></tr><tr><td>复制私钥</td><td>右键菜单</td><td>复制私钥内容</td></tr><tr><td>重命名</td><td>hover 快捷按钮 / 右键菜单</td><td>连带重命名 <code>.pub</code> 文件</td></tr><tr><td>删除</td><td>hover 快捷按钮 / 右键菜单</td><td>见下文删除保护</td></tr></tbody></table><p>复制走 Wails 运行时剪贴板（WKWebView 下浏览器剪贴板 API 不可靠，失败时自动回退）。</p><h2 id="_5-删除保护" tabindex="-1">5. 删除保护 <a class="header-anchor" href="#_5-删除保护" aria-label="Permalink to &quot;5. 删除保护&quot;">​</a></h2><p>删除前会检查密钥是否被连接引用——除按 <code>key_name</code> 关联外，还会<strong>解密各连接的私钥内容逐字节比对</strong>。被引用时拒绝删除并提示：</p><blockquote><p>密钥 &quot;xxx&quot; 正被以下连接使用：…，无法删除</p></blockquote><p>避免删掉密钥后连接全部失效（问题记录见 <code>docs/issues/0007</code>）。</p><h2 id="_6-与连接的关系" tabindex="-1">6. 与连接的关系 <a class="header-anchor" href="#_6-与连接的关系" aria-label="Permalink to &quot;6. 与连接的关系&quot;">​</a></h2><p><a href="./connections.html">连接表单</a>选择私钥认证时，「从密钥管理选择」下拉列出的就是这里的密钥；连接记录会保存 <code>key_name</code>，密钥有口令时在表单中单独输入口令。</p><p>密钥文件本身不受数据库加密体系管理（它就是 <code>~/.ssh</code> 里的普通文件）；存入连接的私钥<strong>内容</strong>才会 AES-256-GCM 加密后进数据库，详见<a href="./../dev/storage-crypto.html">数据存储与加密</a>。</p><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./connections.html">连接与分组管理</a></li><li><a href="./ssh-config.html">~/.ssh/config 导入导出</a> —— config 中的 <code>IdentityFile</code> 与密钥管理的联动</li></ul>',26)])])}const _=d(r,[["render",h]]);export{u as __pageData,_ as default};
